<?php
/**
 * Plugin Name: WP Safe Mode AI — Session Overlay
 * Description: Loads before regular plugins so a signed session cookie can change which plugins and theme that one browser session sees. Installed and removed by the WP Safe Mode AI Toolkit.
 * Version:     0.1.0
 *
 * Do not edit this file directly. It is copied into wp-content/mu-plugins/ by
 * the toolkit and replaced wholesale on update. The source of truth is
 * mu-loader/wpsm-safe-mode.php inside the plugin.
 *
 * This file is deliberately self-contained: must-use plugins load before the
 * regular plugin set, so the toolkit's autoloader does not exist yet and none
 * of its classes can be referenced here.
 *
 * @package WPSM
 */

defined( 'ABSPATH' ) || exit;

/**
 * Resolve and cache the safe-mode session for this request.
 *
 * Returns the session array, or null when the request is an ordinary one —
 * which is every request from every visitor who is not actively troubleshooting.
 *
 * Only the signature and expiry are checked here. This code runs long before
 * the auth cookie is parsed, so it cannot know who the user is; the toolkit
 * re-checks capability on `init` and revokes the session if it does not hold
 * up. The consequence of the gap is a different *view* of the site for the
 * cookie holder, never a different permission.
 *
 * @return array<string, mixed>|null
 */
function wpsm_mu_session() {
	static $resolved = false;
	static $session  = null;

	if ( $resolved ) {
		return $session;
	}

	// Guard against re-entry: this runs inside option filters, and an
	// unexpected recursion here would take the whole site down.
	static $in_progress = false;

	if ( $in_progress ) {
		return null;
	}

	$in_progress = true;

	try {
		$session = wpsm_mu_resolve_session();
	} catch ( Throwable $e ) {
		// A broken session must never be able to break the site. Fail closed:
		// no session means the site renders normally.
		$session = null;
	}

	$in_progress = false;
	$resolved    = true;

	return $session;
}

/**
 * @return array<string, mixed>|null
 */
function wpsm_mu_resolve_session() {
	if ( empty( $_COOKIE['wp-wpsm-session'] ) || ! is_string( $_COOKIE['wp-wpsm-session'] ) ) {
		return null;
	}

	$parts = explode( '.', $_COOKIE['wp-wpsm-session'] );

	if ( 3 !== count( $parts ) ) {
		return null;
	}

	list( $id, $expires, $signature ) = $parts;

	if ( ! preg_match( '/^[a-f0-9]{32}$/', $id ) || ! ctype_digit( $expires ) ) {
		return null;
	}

	if ( (int) $expires < time() ) {
		return null;
	}

	$secret = get_option( 'wpsm_session_secret' );

	if ( ! is_string( $secret ) || strlen( $secret ) < 64 ) {
		return null;
	}

	$expected = hash_hmac( 'sha256', $id . '|' . $expires, $secret );

	if ( ! hash_equals( $expected, $signature ) ) {
		return null;
	}

	$sessions = get_option( 'wpsm_safe_sessions', array() );

	if ( ! is_array( $sessions ) || empty( $sessions[ $id ] ) || ! is_array( $sessions[ $id ] ) ) {
		return null;
	}

	$session = $sessions[ $id ];

	if ( empty( $session['expires'] ) || (int) $session['expires'] < time() ) {
		return null;
	}

	return $session;
}

/**
 * Swap the active plugin list for this session only.
 *
 * @param mixed $plugins Value from the options API.
 * @return mixed
 */
function wpsm_mu_filter_active_plugins( $plugins ) {
	$session = wpsm_mu_session();

	if ( null === $session || ! isset( $session['profile']['plugins'] ) ) {
		return $plugins;
	}

	$allowed = $session['profile']['plugins'];

	if ( ! is_array( $allowed ) ) {
		return $plugins;
	}

	// Intersect rather than replace: a profile must never be able to activate
	// something that is not already active on the live site.
	$live = is_array( $plugins ) ? $plugins : array();

	return array_values( array_intersect( $live, array_map( 'strval', $allowed ) ) );
}

/**
 * Network-activated plugins are stored as an associative array keyed by file.
 *
 * @param mixed $plugins Value from the options API.
 * @return mixed
 */
function wpsm_mu_filter_sitewide_plugins( $plugins ) {
	$session = wpsm_mu_session();

	if ( null === $session || ! isset( $session['profile']['plugins'] ) || ! is_array( $plugins ) ) {
		return $plugins;
	}

	$allowed = array_map( 'strval', (array) $session['profile']['plugins'] );

	return array_intersect_key( $plugins, array_flip( $allowed ) );
}

/**
 * Force the session's stylesheet.
 *
 * @param mixed $stylesheet Current value.
 * @return mixed
 */
function wpsm_mu_filter_stylesheet( $stylesheet ) {
	$session = wpsm_mu_session();

	if ( null === $session || empty( $session['profile']['theme'] ) ) {
		return $stylesheet;
	}

	return (string) $session['profile']['theme'];
}

/**
 * Force the session's template (the parent, when the theme is a child).
 *
 * @param mixed $template Current value.
 * @return mixed
 */
function wpsm_mu_filter_template( $template ) {
	$session = wpsm_mu_session();

	if ( null === $session || empty( $session['profile']['theme'] ) ) {
		return $template;
	}

	$stylesheet = (string) $session['profile']['theme'];
	$theme      = wp_get_theme( $stylesheet );

	if ( ! $theme->exists() ) {
		return $template;
	}

	$parent = $theme->get_template();

	return $parent ? $parent : $stylesheet;
}

/*
 * Both the `pre_option_*` short-circuit and the late `stylesheet`/`template`
 * filters are hooked. Core reads these values through both paths depending on
 * how far through the load it is, and covering only one leaves the theme
 * half-switched.
 */
add_filter( 'option_active_plugins', 'wpsm_mu_filter_active_plugins' );
add_filter( 'site_option_active_sitewide_plugins', 'wpsm_mu_filter_sitewide_plugins' );

add_filter( 'pre_option_stylesheet', 'wpsm_mu_filter_stylesheet' );
add_filter( 'pre_option_template', 'wpsm_mu_filter_template' );
add_filter( 'stylesheet', 'wpsm_mu_filter_stylesheet' );
add_filter( 'template', 'wpsm_mu_filter_template' );

/**
 * Tell the world this request is running under safe mode.
 *
 * Useful when debugging "why does this look different for me" and consumed by
 * the toolkit's admin bar indicator.
 */
add_action(
	'send_headers',
	function () {
		if ( null !== wpsm_mu_session() && ! headers_sent() ) {
			header( 'X-WPSM-Safe-Mode: active' );
		}
	}
);
